mkitem!{mktrait!{# [doc = " Provides the pointer metadata type of any pointed-to type."] # [doc = ""] # [doc = " # Pointer metadata"] # [doc = ""] # [doc = " Raw pointer types and reference types in Rust can be thought of as made of two parts:"] # [doc = " a data pointer that contains the memory address of the value, and some metadata."] # [doc = ""] # [doc = " For statically-sized types (that implement the `Sized` traits)"] # [doc = " as well as for `extern` types,"] # [doc = " pointers are said to be “thin”: metadata is zero-sized and its type is `()`."] # [doc = ""] # [doc = " Pointers to [dynamically-sized types][dst] are said to be “wide” or “fat”,"] # [doc = " they have non-zero-sized metadata:"] # [doc = ""] # [doc = " * For structs whose last field is a DST, metadata is the metadata for the last field"] # [doc = " * For the `str` type, metadata is the length in bytes as `usize`"] # [doc = " * For slice types like `[T]`, metadata is the length in items as `usize`"] # [doc = " * For trait objects like `dyn SomeTrait`, metadata is [`DynMetadata<Self>`][DynMetadata]"] # [doc = "   (e.g. `DynMetadata<dyn SomeTrait>`)"] # [doc = ""] # [doc = " In the future, the Rust language may gain new kinds of types"] # [doc = " that have different pointer metadata."] # [doc = ""] # [doc = " [dst]: https://doc.rust-lang.org/nomicon/exotic-sizes.html#dynamically-sized-types-dsts"] # [doc = ""] # [doc = ""] # [doc = " # The `Pointee` trait"] # [doc = ""] # [doc = " The point of this trait is its `Metadata` associated type,"] # [doc = " which is `()` or `usize` or `DynMetadata<_>` as described above."] # [doc = " It is automatically implemented for every type."] # [doc = " It can be assumed to be implemented in a generic context, even without a corresponding bound."] # [doc = ""] # [doc = ""] # [doc = " # Usage"] # [doc = ""] # [doc = " Raw pointers can be decomposed into the data pointer and metadata components"] # [doc = " with their [`to_raw_parts`] method."] # [doc = ""] # [doc = " Alternatively, metadata alone can be extracted with the [`metadata`] function."] # [doc = " A reference can be passed to [`metadata`] and implicitly coerced."] # [doc = ""] # [doc = " A (possibly-wide) pointer can be put back together from its data pointer and metadata"] # [doc = " with [`from_raw_parts`] or [`from_raw_parts_mut`]."] # [doc = ""] # [doc = " [`to_raw_parts`]: *const::to_raw_parts"] # [lang = "pointee_trait"] # [rustc_deny_explicit_impl] # [rustc_do_not_implement_via_object] pub trait Pointee : PointeeSized { # [doc = " The type for metadata in pointers and references to `Self`."] # [lang = "metadata_type"] type Metadata : fmt :: Debug + Copy + Send + Sync + Ord + Hash + Unpin + Freeze ; }}}
mkitem!{# [doc = " Pointers to types implementing this trait alias are “thin”."] # [doc = ""] # [doc = " This includes statically-`Sized` types and `extern` types."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![feature(ptr_metadata)]"] # [doc = ""] # [doc = " fn this_never_panics<T: std::ptr::Thin>() {"] # [doc = "     assert_eq!(size_of::<&T>(), size_of::<usize>())"] # [doc = " }"] # [doc = " ```"] # [unstable (feature = "ptr_metadata" , issue = "81513")] pub trait Thin = Pointee < Metadata = () > + PointeeSized ;}

macro_rules! metadata_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function metadata in module {}", module_path!());
    };
}

mkfn!{
    metadata_introspect!();
    # [doc = " Extracts the metadata component of a pointer."] # [doc = ""] # [doc = " Values of type `*mut T`, `&T`, or `&mut T` can be passed directly to this function"] # [doc = " as they implicitly coerce to `*const T`."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(ptr_metadata)]"] # [doc = ""] # [doc = " assert_eq!(std::ptr::metadata(\"foo\"), 3_usize);"] # [doc = " ```"] # [inline] pub const fn metadata < T : PointeeSized > (ptr : * const T) -> < T as Pointee > :: Metadata { ptr_metadata (ptr) }
}

macro_rules! from_raw_parts_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function from_raw_parts in module {}", module_path!());
    };
}

mkfn!{
    from_raw_parts_introspect!();
    # [doc = " Forms a (possibly-wide) raw pointer from a data pointer and metadata."] # [doc = ""] # [doc = " This function is safe but the returned pointer is not necessarily safe to dereference."] # [doc = " For slices, see the documentation of [`slice::from_raw_parts`] for safety requirements."] # [doc = " For trait objects, the metadata must come from a pointer to the same underlying erased type."] # [doc = ""] # [doc = " If you are attempting to deconstruct a DST in a generic context to be reconstructed later,"] # [doc = " a thin pointer can always be obtained by casting `*const T` to `*const ()`."] # [doc = ""] # [doc = " [`slice::from_raw_parts`]: crate::slice::from_raw_parts"] # [unstable (feature = "ptr_metadata" , issue = "81513")] # [inline] pub const fn from_raw_parts < T : PointeeSized > (data_pointer : * const impl Thin , metadata : < T as Pointee > :: Metadata ,) -> * const T { aggregate_raw_ptr (data_pointer , metadata) }
}

macro_rules! from_raw_parts_mut_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function from_raw_parts_mut in module {}", module_path!());
    };
}

mkfn!{
    from_raw_parts_mut_introspect!();
    # [doc = " Performs the same functionality as [`from_raw_parts`], except that a"] # [doc = " raw `*mut` pointer is returned, as opposed to a raw `*const` pointer."] # [doc = ""] # [doc = " See the documentation of [`from_raw_parts`] for more details."] # [unstable (feature = "ptr_metadata" , issue = "81513")] # [inline] pub const fn from_raw_parts_mut < T : PointeeSized > (data_pointer : * mut impl Thin , metadata : < T as Pointee > :: Metadata ,) -> * mut T { aggregate_raw_ptr (data_pointer , metadata) }
}
mkitem!{mkstruct!{# [doc = " The metadata for a `Dyn = dyn SomeTrait` trait object type."] # [doc = ""] # [doc = " It is a pointer to a vtable (virtual call table)"] # [doc = " that represents all the necessary information"] # [doc = " to manipulate the concrete type stored inside a trait object."] # [doc = " The vtable notably contains:"] # [doc = ""] # [doc = " * type size"] # [doc = " * type alignment"] # [doc = " * a pointer to the type’s `drop_in_place` impl (may be a no-op for plain-old-data)"] # [doc = " * pointers to all the methods for the type’s implementation of the trait"] # [doc = ""] # [doc = " Note that the first three are special because they’re necessary to allocate, drop,"] # [doc = " and deallocate any trait object."] # [doc = ""] # [doc = " It is possible to name this struct with a type parameter that is not a `dyn` trait object"] # [doc = " (for example `DynMetadata<u64>`) but not to obtain a meaningful value of that struct."] # [doc = ""] # [doc = " Note that while this type implements `PartialEq`, comparing vtable pointers is unreliable:"] # [doc = " pointers to vtables of the same type for the same trait can compare inequal (because vtables are"] # [doc = " duplicated in multiple codegen units), and pointers to vtables of *different* types/traits can"] # [doc = " compare equal (since identical vtables can be deduplicated within a codegen unit)."] # [lang = "dyn_metadata"] pub struct DynMetadata < Dyn : PointeeSized > { _vtable_ptr : NonNull < VTable > , _phantom : crate :: marker :: PhantomData < Dyn > , }}}
mkitem!{unsafe extern "C" { # [doc = " Opaque type for accessing vtables."] # [doc = ""] # [doc = " Private implementation detail of `DynMetadata::size_of` etc."] # [doc = " There is conceptually not actually any Abstract Machine memory behind this pointer."] type VTable ; }}
mkitem!{mkimpl!{impl < Dyn : PointeeSized > DynMetadata < Dyn > { # [doc = " When `DynMetadata` appears as the metadata field of a wide pointer, the rustc_middle layout"] # [doc = " computation does magic and the resulting layout is *not* a `FieldsShape::Aggregate`, instead"] # [doc = " it is a `FieldsShape::Primitive`. This means that the same type can have different layout"] # [doc = " depending on whether it appears as the metadata field of a wide pointer or as a stand-alone"] # [doc = " type, which understandably confuses codegen and leads to ICEs when trying to project to a"] # [doc = " field of `DynMetadata`. To work around that issue, we use `transmute` instead of using a"] # [doc = " field projection."] # [inline] fn vtable_ptr (self) -> * const VTable { unsafe { crate :: mem :: transmute :: < Self , * const VTable > (self) } } # [doc = " Returns the size of the type associated with this vtable."] # [inline] pub fn size_of (self) -> usize { unsafe { crate :: intrinsics :: vtable_size (self . vtable_ptr () as * const ()) } } # [doc = " Returns the alignment of the type associated with this vtable."] # [inline] pub fn align_of (self) -> usize { unsafe { crate :: intrinsics :: vtable_align (self . vtable_ptr () as * const ()) } } # [doc = " Returns the size and alignment together as a `Layout`"] # [inline] pub fn layout (self) -> crate :: alloc :: Layout { unsafe { crate :: alloc :: Layout :: from_size_align_unchecked (self . size_of () , self . align_of ()) } } }}}
